    v1 = vars["v1"]
    v2 = vars["v2"]
    total_shares_repur chased = v1 + v2

    return {
        "value": total_shares_repur chased,
        "trace": {
            "v1": v1,
            "v2": v2,
            "total_shares_repur chased": total_shares_repur chased,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "shares"
            }
        }
    }
